from collections import deque

h, w = 14, 14

def flood_fill_from_point(start_r, start_c, avoid_cells):
    """Flood fill from a starting point, avoiding avoid_cells"""
    visited = set()
    q = deque([(start_r, start_c)])
    visited.add((start_r, start_c))

    while q:
        r, c = q.popleft()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in avoid_cells and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))

    return visited

